import{a as e,i as t,r as n,t as r}from"./app-Cwfdj7tv.js";var i=JSON.parse(`{"path":"/guide/arcade.html","title":"街机厅","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1790405684000,"contributors":[{"name":"ShiroMizu","username":"","email":"ShiroMizuTan@163.com","commits":6}],"changelog":[{"hash":"44ddac8ae97e55ade0c80cba0123eead160887e7","time":1790405684000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: add sauce page, sync arcade prefixless and maimai updates"},{"hash":"773bd574bdd7c9d39c1352376ce7928c3358afb3","time":1787771416000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: sync with latest COMMANDS.md"},{"hash":"3a2020b47139cbd549e92f2b43b5477ec3da578a","time":1787575055000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: update documentation"},{"hash":"c8f72ace24131d7692aae7675d3b3f124a3351ad","time":1787271196000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: add maimai documentation"},{"hash":"e8700d705b080ed91fb8d8313ce8c8d3e1abd968","time":1785942415000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: update namachoko-docs content"},{"hash":"9435fedfa15b95959815b42ddc992096b875dd8b","time":1785003572000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"feat: add namachoko-docs (VuePress documentation)"}]},"filePathRelative":"guide/arcade.md"}`),a={name:`arcade.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="街机厅" tabindex="-1"><a class="header-anchor" href="#街机厅"><span>街机厅</span></a></h1><h2 id="地点与别名" tabindex="-1"><a class="header-anchor" href="#地点与别名"><span>地点与别名</span></a></h2><h3 id="查找地点" tabindex="-1"><a class="header-anchor" href="#查找地点"><span>查找地点</span></a></h3><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>查找地点</code> / <code>找地点</code> / <code>查地点</code></td><td><code>关键词</code></td><td><code>.查找地点 秋叶原</code></td><td>按名称、地址或省份搜索街机厅</td></tr></tbody></table><h3 id="添加别名" tabindex="-1"><a class="header-anchor" href="#添加别名"><span>添加别名</span></a></h3><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>添加别名</code> / <code>新增别名</code></td><td><code>别名 地点ID</code></td><td><code>.添加别名 秋叶原 12345</code></td><td>为街机厅设置当前群别名</td></tr></tbody></table><p>先用 <code>.查找地点</code> 获取地点 ID，再用 <code>.添加别名 别名 地点ID</code>。</p><h3 id="删除别名" tabindex="-1"><a class="header-anchor" href="#删除别名"><span>删除别名</span></a></h3><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>删除别名</code> / <code>移除别名</code></td><td><code>别名</code></td><td><code>.删除别名 秋叶原</code></td><td>删除当前群的指定别名</td></tr></tbody></table><h3 id="别名列表" tabindex="-1"><a class="header-anchor" href="#别名列表"><span>别名列表</span></a></h3><table><thead><tr><th>指令</th><th>说明</th></tr></thead><tbody><tr><td><code>别名列表</code> / <code>列出别名</code></td><td>查看地点别名</td></tr></tbody></table><h2 id="人数查询" tabindex="-1"><a class="header-anchor" href="#人数查询"><span>人数查询</span></a></h2><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>jk</code></td><td>无</td><td><code>.jk</code></td><td>查看当前群最近 4 小时所有地点的最新上报</td></tr><tr><td><code>jk</code></td><td><code>别名</code></td><td><code>.jk cw</code></td><td>查看指定别名的最新人数详情</td></tr><tr><td><code>jk</code></td><td><code>小时数</code></td><td><code>.jk 8</code></td><td>查看最近 8 小时所有地点的上报</td></tr><tr><td><code>jk</code></td><td><code>别名 小时数</code></td><td><code>.jk cw 4</code></td><td>查看指定别名最近 4 小时的上报</td></tr><tr><td><code>查询人数</code> / <code>多少人</code></td><td><code>别名 小时数</code></td><td><code>.查询人数 cw 4</code></td><td>查询指定别名最近 N 小时的上报</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">提示</p><p><code>.jk</code> 后的别名和小时数均为可选参数。</p></div><h2 id="人数上报" tabindex="-1"><a class="header-anchor" href="#人数上报"><span>人数上报</span></a></h2><h3 id="普通上报" tabindex="-1"><a class="header-anchor" href="#普通上报"><span>普通上报</span></a></h3><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>上报</code> / <code>上报人数</code></td><td><code>别名 人数</code></td><td><code>.上报 cw 20</code></td><td>直接上报当前人数</td></tr><tr><td><code>上报</code> / <code>上报人数</code></td><td><code>别名 + 人数</code></td><td><code>.上报 cw +5</code></td><td>在最近一次人数基础上增加人数</td></tr><tr><td><code>上报</code> / <code>上报人数</code></td><td><code>别名 - 人数</code></td><td><code>.上报 cw -3</code></td><td>在最近一次人数基础上减少人数</td></tr><tr><td><code>上报</code> / <code>上报人数</code></td><td><code>别名 = 人数</code></td><td><code>.上报 cw =18</code></td><td>直接设置当前人数</td></tr></tbody></table><p>普通上报的人数上限为：<code>机器数量 × 30</code>。</p><div class="hint-container tip"><p class="hint-container-title">提示</p><p>上报支持快捷格式：<code>.别名+数字</code>、<code>.别名-数字</code>、<code>.别名=数字</code>。</p></div><h3 id="强制上报" tabindex="-1"><a class="header-anchor" href="#强制上报"><span>强制上报</span></a></h3><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>强制上报</code> / <code>强制</code></td><td><code>别名 人数</code></td><td><code>.强制上报 cw 500</code></td><td>跳过合理人数检查后上报（当前实现未限制管理员）</td></tr><tr><td><code>强制上报</code> / <code>强制</code></td><td><code>别名 操作符 人数</code></td><td><code>.强制上报 cw +100</code></td><td>强制执行加、减或赋值上报</td></tr></tbody></table><h2 id="无前缀匹配" tabindex="-1"><a class="header-anchor" href="#无前缀匹配"><span>无前缀匹配</span></a></h2><p>群主 / 群管理员 / Bot 管理员可以为当前群开启无前缀匹配。开启后，群成员可以<strong>不带 <code>.</code> 前缀</strong>直接使用街机厅指令：</p><table><thead><tr><th>写法</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>&lt;别名&gt;数字</code> / <code>&lt;别名&gt;±数字</code></td><td><code>cw1</code>、<code>cw+5</code>、<code>cw-3</code>、<code>cw=18</code></td><td>免前缀上报人数，等价于 <code>.cw1</code> 等粘连格式</td></tr><tr><td><code>上报 别名 人数</code></td><td><code>上报 cw 20</code></td><td>免前缀上报，参数必须完整（别名 + 人数），否则不响应</td></tr><tr><td><code>&lt;别名&gt;几</code></td><td><code>cw几</code></td><td>查询单店人数详情</td></tr><tr><td>查询类指令</td><td><code>别名列表</code>、<code>多少人 cw</code></td><td>免前缀查询（<code>查找地点</code>、<code>查询人数</code>、<code>别名列表</code>、<code>多少人</code> 等）</td></tr></tbody></table><table><thead><tr><th>指令</th><th>示例</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>开启街机无前缀</code> / <code>启用街机无前缀</code></td><td><code>.开启街机无前缀</code></td><td>群主 / 群管理员 / Bot 管理员</td><td>为当前群开启无前缀匹配</td></tr><tr><td><code>关闭街机无前缀</code> / <code>停用街机无前缀</code></td><td><code>.关闭街机无前缀</code></td><td>群主 / 群管理员 / Bot 管理员</td><td>为当前群关闭无前缀匹配</td></tr></tbody></table><div class="hint-container warning"><p class="hint-container-title">注意</p><ul><li>无前缀匹配仅限 QQ 群聊，且<strong>默认关闭</strong>，需要手动开启</li><li>触发词不匹配或格式不完整时 Bot 静默不响应</li><li>写类管理指令（添加别名 / 删除别名 / 强制上报）不在无前缀范围内，仍需 <code>.</code> 前缀</li></ul></div>`,26)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};